n.loginUrl:
function login() {
    java.log("模拟登录请求");
    cookie.removeCookie(source.key)
    res = source.getLoginInfoMap()

    use=res.get("帐号");
    pwd=res.get("密码");

    code=java.getVerificationCode("https://www.lsxs.org/code.jpg?"+Math.random())

    body=`user_name=${use}&user_pass=${java.md5Encode(pwd)}&user_code=${code}`

   headers= {
    "accept": "*/*",
    "accept-language": "zh-CN,zh;q=0.9",
    "cache-control": "no-cache",
    "content-type": "application/x-www-form-urlencoded; charset=UTF-8",
    "pragma": "no-cache",
    "x-requested-with": "XMLHttpRequest",
    "Referer": "https://www.lsxs.org",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "User-Agent": "Mozilla/5.0 (Linux; Android 15; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/133.0.0.9 Mobile Safari/537.36"
  }
    html=java.ajax("https://www.lsxs.org/qs_login_go.php,"+JSON.stringify({
  "body": body,
  "method": "POST",
  "headers": JSON.stringify(headers)
    	}))

    java.longToast(html)
    Packages.java.lang.Thread.sleep(1000)

}
